function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function safeImg(src,fallback=LOGO){return (typeof src==='string'&&src.trim())?src:fallback}
function renderHero(){heroSettings=load('lf_hero',DEFAULT_HERO)||DEFAULT_HERO;const logo=document.getElementById('logo'),hero=document.getElementById('heroLogo'),side=document.getElementById('sideLogo');if(logo){logo.src=safeImg(heroSettings.logo);logo.onerror=()=>{logo.onerror=null;logo.src=LOGO}}if(hero){hero.src=safeImg(heroSettings.image);hero.onerror=()=>{hero.onerror=null;hero.src=LOGO}}if(side){side.src=safeImg(heroSettings.logo);side.onerror=()=>{side.onerror=null;side.src=LOGO}}}
function renderCats(){const keys=Object.keys(cats);const countBy={};products.forEach(p=>countBy[p.cat]=(countBy[p.cat]||0)+1);const catsEl=document.getElementById('cats');if(catsEl)catsEl.innerHTML=keys.map(k=>{const c=cats[k]||{};return `<button class="cat" onclick="setCat('${esc(k).replace(/'/g,"\'")}')"><img src="${safeImg(c.image,LOGO)}" onerror="this.onerror=null;this.src='${LOGO}'"><label>${esc(currentLang==='en'?(c.en||c.ar||k):(c.ar||k))}</label></button>`}).join('');const filter=document.getElementById('filter');if(filter)filter.innerHTML=`<option value="">${currentLang==='en'?'All categories':'كل الفئات'}</option>`+keys.map(k=>`<option value="${esc(k)}">${esc(currentLang==='en'?(cats[k]?.en||cats[k]?.ar||k):(cats[k]?.ar||k))}</option>`).join('');const bf=document.getElementById('brandFilter');if(bf)bf.innerHTML=`<option value="">${currentLang==='en'?'All brands':'كل البراندات'}</option>`+Object.keys(brands).map(k=>`<option value="${esc(k)}">${esc(currentLang==='en'?(brands[k]?.en||brands[k]?.ar||k):(brands[k]?.ar||k))}</option>`).join('');const side=document.getElementById('sideCats');if(side)side.innerHTML=keys.map(k=>{const c=cats[k]||{};return `<button class="sideCat" onclick="setCat('${esc(k).replace(/'/g,"\'")}');toggleSideMenu()"><img src="${safeImg(c.image,LOGO)}" onerror="this.onerror=null;this.src='${LOGO}'"><b>${esc(currentLang==='en'?(c.en||c.ar||k):(c.ar||k))}</b><span>${countBy[k]||0}</span></button>`}).join('');const sideB=document.getElementById('sideBrands');if(sideB)sideB.innerHTML=Object.keys(brands).map(k=>{const b=brands[k]||{};const n=products.filter(p=>p.brand===k).length;return `<button class="sideCat" onclick="setBrand('${esc(k).replace(/'/g,"\'")}');toggleSideMenu()"><img src="${safeImg(b.image,LOGO)}" onerror="this.onerror=null;this.src='${LOGO}'"><b>${esc(currentLang==='en'?(b.en||b.ar||k):(b.ar||k))}</b><span>${n}</span></button>`}).join('')}
