function joinWaitlist(id){const p=products.find(x=>x.id===id);if(!p)return;const name=prompt(currentLang==='en'?'Your name:':'اسمك:');if(!name)return;const phone=prompt(currentLang==='en'?'WhatsApp number:':'رقم واتسابك:');if(!phone)return;let w=load('lf_waitlist',[]);w.push({id:Date.now(),productId:id,productName:p.name,en:p.en,variant:'',name,phone:normalizePhone(phone),date:new Date().toISOString(),notified:false});save('lf_waitlist',w);alert(currentLang==='en'?'You have been added to the availability list. We will contact you when it is available.':'💕 تم تسجيلك في قائمة التوفر. سنراسلك على واتساب عند توفره 🌸')}
function openPolicy(type){const en=currentLang==='en';const text=type==='returns'?(en?'<h2>Exchange & Return Policy</h2><p>Please contact the store within 12 hours of receiving the order for exchange or return requests. The item must be unused and in its original condition and packaging. Clearance, opened cosmetics, and perfumes cannot be returned unless there is a defect.</p><p>Shipping/return costs are handled according to the reason for return and the store confirmation.</p>':'<h2>سياسة التبديل والإرجاع</h2><p>يرجى التواصل مع المتجر خلال 12 ساعة من استلام الطلب لطلبات التبديل أو الإرجاع. يجب أن يكون المنتج غير مستخدم وبحالته وتغليفه الأصليين. المنتجات المخفضة جدًا ومستحضرات التجميل والعطور المفتوحة لا تُرجع إلا في حال وجود عيب.</p><p>تكاليف الشحن أو الإرجاع تحدد حسب سبب الإرجاع وبعد تأكيد المتجر.</p>'):(en?'<h2>Privacy</h2><p>Your order information is used only to process and contact you about your order.</p>':'<h2>الخصوصية</h2><p>تُستخدم بيانات الطلب فقط لمعالجة الطلب والتواصل معك بخصوصه.</p>');document.getElementById('policyContent').innerHTML=text;document.getElementById('policyModal').style.display='flex'}
function closePolicy(){document.getElementById('policyModal').style.display='none'}
function shippingInfo(region){const map={westbank:{fee:20,ar:'الضفة الغربية',en:'West Bank'},jerusalem:{fee:35,ar:'القدس',en:'Jerusalem'},inside:{fee:70,ar:'الداخل',en:'Inside 1948'}};return map[region]||map.westbank}
function currentShipping(){const r=document.getElementById('shippingRegion')?.value||'westbank';return shippingInfo(r)}
function isOfferActive(p){return !!p.onSale&&Number(p.old)>Number(p.price)&&(!p.offerExpiry||new Date(p.offerExpiry+'T23:59:59').getTime()>=Date.now())}
function weeklyOrderDate(o){const raw=o?.createdAt||o?.timestamp||o?.date;const d=raw instanceof Date?raw:new Date(raw);return Number.isNaN(d.getTime())?null:d}
function isThisWeekOrder(o){const d=weeklyOrderDate(o);return !!d&&d.getTime()>=Date.now()-7*24*60*60*1000}
function salesMap(orders){const m={};(orders||[]).forEach(o=>(o.items||[]).forEach(it=>{const id=it.productId??it.id;if(id==null)return;m[String(id)]=(m[String(id)]||0)+(Number(it.qty)||0)}));return m}
function getTop5(){
  const eligible=products.filter(p=>totalStock(p)>0);
  const offers=eligible.filter(p=>isOfferActive(p));
  const pool=offers.length?offers:eligible;
  return [...pool].sort((a,b)=>{const am=a.top5?1:0,bm=b.top5?1:0;if(am!==bm)return bm-am;const ad=Number(a.old)>Number(a.price)?(Number(a.old)-Number(a.price))/Math.max(1,Number(a.old)):0;const bd=Number(b.old)>Number(b.price)?(Number(b.old)-Number(b.price))/Math.max(1,Number(b.old)):0;return bd-ad}).slice(0,5);
}
function getBestSellers(){
  const server=Array.isArray(window.LF_BEST_SELLERS)?window.LF_BEST_SELLERS:null;
  if(server){return server.map(x=>({p:products.find(p=>String(p.id)===String(x.productId)),qty:Number(x.quantity)||0})).filter(x=>x.p&&totalStock(x.p)>0).slice(0,5);}
  const all=load('lf_orders',[]).filter(o=>o.status!=='ملغي');
  const week=all.filter(isThisWeekOrder);
  const weeklyMap=salesMap(week), allMap=salesMap(all);
  const useMap=Object.keys(weeklyMap).length?weeklyMap:allMap;
  return Object.entries(useMap).map(([id,qty])=>({p:products.find(p=>String(p.id)===String(id)),qty})).filter(x=>x.p&&totalStock(x.p)>0).sort((a,b)=>b.qty-a.qty).slice(0,5);
}
function scrollFeature(id,dir){const el=document.getElementById(id);if(!el)return;const amount=Math.max(180,Math.round(el.clientWidth*.72));const before=el.scrollLeft;el.scrollBy({left:dir==='left'?-amount:amount,behavior:'smooth'});setTimeout(()=>{if(Math.abs(el.scrollLeft-before)<2){const max=Math.max(0,el.scrollWidth-el.clientWidth);if(max>8)el.scrollLeft=dir==='left'?Math.max(0,before-amount):Math.min(max,before+amount)}},450);}
const ACCOUNT_KEY='lf_account', FAV_KEY='lf_favorites';
function getAccount(){
  const account=load(ACCOUNT_KEY,null);
  if(!account)return null;
  const users=load('lf_users',[]);
  if(!Array.isArray(users)||!users.length)return account;
  let user=null;
  if(account.id!=null) user=users.find(u=>String(u.id||'')===String(account.id));
  if(!user) user=users.find(u=>u.type===account.type&&String(u.contact||'').trim().toLowerCase()===String(account.contact||'').trim().toLowerCase());
  if(!user)return account;
  const synced={...account,...user,password:account.password||user.password};
  if(JSON.stringify(synced)!==JSON.stringify(account)) save(ACCOUNT_KEY,synced);
  return synced;
}
function getFavorites(){return load(FAV_KEY,[]).map(Number).filter(id=>products.some(p=>Number(p.id)===id))}
function saveFavorites(v){save(FAV_KEY,[...new Set(v.map(Number))]);updateAccountBadge()}
function isFavorite(id){return getFavorites().includes(Number(id))}
function toggleFavorite(id){const fav=getFavorites(),n=Number(id);saveFavorites(fav.includes(n)?fav.filter(x=>x!==n):fav.concat(n));renderProducts();renderQuickOffers();if(document.getElementById('accountModal')?.style.display==='flex')renderAccountContent()}
function favoriteCards(){return getFavorites().map(id=>products.find(p=>Number(p.id)===id)).filter(Boolean).map(p=>{const img=safeImg(mainImagesOf(p)[0],LOGO);return `<div class="favCard"><img src="${img}" onclick="openProduct(${p.id})"><div class="fcbody"><b>${esc(currentLang==='en'?(p.en||p.name):p.name)}</b><div>${Number(p.price)||0} ₪</div><button onclick="addSingleToCart(${p.id},selectedVariant(${p.id}));renderAccountContent()">🛍️ نقل للسلة</button><button onclick="toggleFavorite(${p.id})">♥ إزالة</button></div></div>`}).join('')}
function openAccount(){document.getElementById('accountModal').style.display='flex';renderAccountContent()}
function closeAccount(){document.getElementById('accountModal').style.display='none'}
function getAccountOrders(){const a=getAccount();if(!a)return [];return load('lf_orders',[]).filter(o=>o.status!=='ملغي'&&(o.accountRef===a.contact||(a.type==='whatsapp'&&normalizePhone(o.phone)===normalizePhone(a.contact)))).slice(0,20)}
function orderDetailsHtml(o){const items=(o.items||[]).map(it=>`<div class="orderItem"><div><b>${esc(it.name||'منتج')}</b>${it.variant?`<div>اللون: ${esc(it.variant)}</div>`:''}${it.packagingName?`<div>🎁 ${esc(it.packagingName)} +${Number(it.packagingPrice)||0} ₪</div>`:''}</div><span>× ${Number(it.qty)||1}</span><b>${Number(it.lineTotal||0).toFixed(2)} ₪</b></div>`).join('');return `<div class="orderDetail"><div class="orderDetailHead"><b>الطلب #${o.id}</b><span>${esc(o.date||'')}</span></div><div class="orderItems">${items||'<div class="empty">لا توجد تفاصيل.</div>'}</div><div class="orderSummary">المجموع الفرعي: ${Number(o.subtotal||0).toFixed(2)} ₪<br>التوصيل: ${o.shippingWaived?'معفى':Number(o.shippingFee||0).toFixed(2)+' ₪'}${Number(o.couponDiscount)>0?`<br>خصم الكوبون: -${Number(o.couponDiscount).toFixed(2)} ₪`:''}${Number(o.loyaltyDiscount)>0?`<br>⭐ خصم استبدال النقاط: -${Number(o.loyaltyDiscount).toFixed(2)} ₪ (${Number(o.pointsRedeemed||0)} نقطة)`:''}<br><b>الإجمالي: ${Number(o.total||0).toFixed(2)} ₪</b></div><button class="add" type="button" onclick="reorder(${o.id})">🔄 إعادة الطلب</button></div>`}
function viewOrder(id){const o=load('lf_orders',[]).find(x=>String(x.id)===String(id));if(!o)return;const m=document.getElementById('orderDetailModal');if(!m)return;document.getElementById('orderDetailContent').innerHTML=orderDetailsHtml(o);m.style.display='flex'}
function closeOrderDetail(){const m=document.getElementById('orderDetailModal');if(m)m.style.display='none'}
function reorder(id){const o=load('lf_orders',[]).find(x=>String(x.id)===String(id));if(!o)return;let added=0,skipped=0;(o.items||[]).forEach(it=>{const p=products.find(x=>Number(x.id)===Number(it.productId));if(!p){skipped++;return}const available=variantStock(p,it.variant||'');const want=Math.max(1,Number(it.qty)||1);if(available<=0){skipped++;return}const qty=Math.min(want,available);addToCart(p.id,qty,it.variant||'',it.packagingId||'');added+=qty;if(qty<want)skipped++});closeOrderDetail();closeAccount();openCart();if(skipped)alert(`تمت إعادة إضافة ${added} قطعة 🌸\n${skipped} من القطع لم تعد متوفرة بالكمية المطلوبة.`)}
function renderSideAccountGreeting(){const el=document.getElementById('sideAccountGreeting');if(!el)return;const a=getAccount();el.innerHTML=a?`<div class="sideGreeting">${greetingForAccount(a)}، <b>${esc(a.name||'سيدتي')}</b> 🩷</div><button class="sideAccountBtn" onclick="openAccount();toggleSideMenu()">👤 حسابي وطلباتي</button>`:`<button class="sideAccountBtn" onclick="openAccount();toggleSideMenu()">👤 تسجيل الدخول الاختياري</button>`}
function localPhoneForAccount(a){const raw=String(a?.contact||'').trim();if(!raw)return '';const n=normalizePhone(raw,a?.countryIso||'PS');if(!n.startsWith('+'))return raw;const dial=String(COUNTRY_DIAL_CODES[a?.countryIso||'PS']||'');if(dial&&n.slice(1,1+dial.length)===dial)return '0'+n.slice(1+dial.length);return n.slice(1)}
function renderAccountContent(){const el=document.getElementById('accountContent');if(!el)return;const a=getAccount(),fav=getFavorites(),orders=getAccountOrders();renderSideAccountGreeting();if(!a){el.innerHTML=`<div class="notice">تسجيل الدخول اختياري، ويحفظ السلة والمفضلة وتفاصيل مشترياتك على هذا الجهاز.</div><div class="accountMode"><button id="modeWhats" class="active" onclick="setAccountMode('whatsapp')">💬 واتساب</button><button id="modeEmail" onclick="setAccountMode('email')">✉️ إيميل</button></div><input id="accountName" class="field" placeholder="الاسم"><div class="genderRow"><select id="accountGender" class="field"><option value="female">أنثى</option><option value="male">ذكر</option></select><input id="accountAge" class="field" type="number" min="13" max="120" placeholder="العمر"></div><div id="accountPhoneBox" class="phoneIntlBox"><div class="phoneIntlTop"><select id="accountCountryCode" class="field countrySelect" onchange="syncCountryDialPreview('accountCountryCode','accountContact')"></select><span class="phoneDialHint" id="accountDialHint">+970</span><button id="gpsCountryBtn" type="button" class="gpsBtn" onclick="detectCountryByGPS('accountCountryCode')">📍 تحديد الدولة تلقائيًا</button></div><input id="accountContact" class="field" placeholder="رقم الواتساب بدون مفتاح الدولة" inputmode="tel" autocomplete="tel-national"></div><div class="gpsNote">📍 الموقع اختياري ويُستخدم فقط لتحديد الدولة تلقائيًا، ولا نحتاج حفظ إحداثياتك.</div><input id="accountPassword" class="field" type="password" minlength="4" placeholder="كلمة المرور"><div class="passwordNote">كلمة المرور تُستخدم للحساب، ويمكن للإدارة إصدار كلمة مرور مؤقتة عند الحاجة.</div><button class="add" onclick="saveAccount()">حفظ الحساب</button><hr><h3>❤️ المفضلة (${fav.length})</h3><div class="favoritesRow">${fav.length?favoriteCards():'<div class="empty">لم تضيفي منتجات للمفضلة بعد.</div>'}</div>`;return}const waChecked=a.whatsapp_opt_in===true||a.whatsapp_opt_in===1||a.whatsapp_opt_in==='1'||a.whatsapp_opt_in==='true';const contactEditor=a.type==='whatsapp'?`<div class="accountContactEditor"><b>🌍 الدولة ومفتاح واتساب</b><div class="phoneIntlTop"><select id="accountCountryEdit" class="field countrySelect" onchange="syncCountryDialPreview('accountCountryEdit','accountContactEdit')"></select><span class="phoneDialHint" id="accountDialEdit">+970</span><button id="gpsCountryEditBtn" type="button" class="gpsBtn" onclick="detectCountryByGPS('accountCountryEdit')">📍 تحديد تلقائي</button></div><input id="accountContactEdit" class="field phoneValueLtr" dir="ltr" inputmode="tel" autocomplete="tel-national" value="${esc(localPhoneForAccount(a))}" placeholder="رقم واتسابك بدون مفتاح الدولة"><button class="add secondaryAdd" type="button" onclick="updateAccountWhatsAppNumber()">حفظ الدولة / المفتاح / الرقم</button><div class="gpsNote">يمكنك تغيير الدولة أو المفتاح يدويًا في أي وقت حتى لو استخدمتِ GPS.</div></div>`:'';el.innerHTML=`<div class="accountGreeting">${greetingForAccount(a)}، ${esc(a.name||'سيدتي')} 🩷</div><div class="success"><div class="accountContactValue">${a.type==='email'?'✉️ ':'💬 '}<span class="phoneValueLtr" dir="ltr">${esc(a.contact)}</span></div><b>⭐ نقاطي: ${Number(a.points||0)}</b><br><label class="waPreference"><input id="waOptIn" type="checkbox" ${waChecked?'checked':''}> أوافق على استلام رسائل واتساب لطيفة عن السلة والمنتجات التي اخترتها والعروض ذات الصلة.</label><div class="accountActionRow"><button type="button" onclick="saveWhatsAppOptIn()">حفظ تفضيلات واتساب</button><button type="button" onclick="logoutAccount()">تسجيل خروج</button></div></div>${contactEditor}<h3>❤️ المفضلة (${fav.length})</h3><div class="favoritesRow">${fav.length?favoriteCards():'<div class="empty">لم تضيفي منتجات للمفضلة بعد.</div>'}</div><h3>🛍️ السلة الحالية: ${cart.length} أصناف</h3><button class="add" onclick="closeAccount();openCart()">فتح السلة</button><h3 style="margin-top:16px">📋 مشترياتي السابقة</h3><div class="ordersList">${orders.length?orders.map(o=>`<div class="orderSummaryCard"><div><b>#${o.id}</b><br><small>${esc(o.date||'')}</small></div><div><b>${Number(o.total||0).toFixed(2)} ₪</b><br><small>${esc(o.status||'جديد')}</small></div><button type="button" onclick="viewOrder(${o.id})">التفاصيل</button></div>`).join(''):'<div class="empty">لا توجد طلبات محفوظة لهذا الحساب بعد.</div>'}</div>`;if(a.type==='whatsapp'){initCountrySelectors();const sel=document.getElementById('accountCountryEdit');if(sel){sel.value=a.countryIso||'PS';syncCountryDialPreview('accountCountryEdit','accountContactEdit')}}}

let accountMode='whatsapp';
function setAccountMode(mode){accountMode=mode;const w=document.getElementById('modeWhats'),e=document.getElementById('modeEmail'),c=document.getElementById('accountContact'),box=document.getElementById('accountPhoneBox');if(w&&e){w.classList.toggle('active',mode==='whatsapp');e.classList.toggle('active',mode==='email')}if(c){c.type=mode==='email'?'email':'tel';c.placeholder=mode==='email'?'البريد الإلكتروني':'رقم الواتساب بدون مفتاح الدولة'}if(box)box.style.display=mode==='email'?'none':'block'}
function greetingForAccount(a){return a?.gender==='male'?'نورتنا':'نورتينا'}
function registerUserRecord(account){let users=load('lf_users',[]);const key=(account.type||'')+':'+String(account.contact||'').trim().toLowerCase();const i=users.findIndex(u=>((u.type||'')+':'+String(u.contact||'').trim().toLowerCase())===key);const rec={...account,id:i>=0?users[i].id:Date.now(),updatedAt:Date.now()};if(i>=0)users[i]=rec;else users.unshift(rec);save('lf_users',users)}
function saveAccount(){const name=document.getElementById('accountName')?.value.trim(),contactRaw=document.getElementById('accountContact')?.value.trim(),countryIso=document.getElementById('accountCountryCode')?.value||'PS',contact=accountMode==='whatsapp'?normalizePhone(contactRaw,countryIso):contactRaw,gender=document.getElementById('accountGender')?.value||'female',age=Math.max(13,Math.min(120,Number(document.getElementById('accountAge')?.value)||0)),password=document.getElementById('accountPassword')?.value||'';if(!name||!contactRaw||!age||!password)return alert('أدخلي الاسم والجنس والعمر ووسيلة التواصل وكلمة المرور');if(password.length<8)return alert('كلمة المرور يجب أن تكون 8 أحرف/أرقام على الأقل');if(accountMode==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactRaw))return alert('أدخلي بريدًا إلكترونيًا صحيحًا');if(accountMode==='whatsapp'&&!validMobile(contactRaw,countryIso))return alert('أدخلي رقم واتساب صحيحًا مع اختيار الدولة');const existing=load(ACCOUNT_KEY,null);const account={name,contact,type:accountMode,gender,age,password,id:existing?.id||Date.now(),createdAt:existing?.createdAt||Date.now(),updatedAt:Date.now()};save(ACCOUNT_KEY,account);registerUserRecord(account);renderAccountContent();initCountrySelectors();syncCountryDialPreview('accountCountryCode','accountContact');updateAccountBadge()}
function logoutAccount(){localStorage.removeItem(ACCOUNT_KEY);renderAccountContent();updateAccountBadge()}
function updateAccountBadge(){const a=getAccount(),b=document.getElementById('accountBtn');if(b){b.innerHTML=a?'👤<i class="accountBadge">✓</i>':'👤';b.title=a?`${greetingForAccount(a)}، ${a.name||'سيدتي'} 🩷`:'حسابي';b.setAttribute('aria-label',b.title)}}
function quickOffers(){const now=Date.now();return products.filter(p=>p.quickOffer&&(!p.quickOfferExpiry||new Date(p.quickOfferExpiry+'T23:59:59').getTime()>=now)&&totalStock(p)>0).slice(0,8)}
function shareOfferWhatsApp(id){const p=products.find(x=>x.id===id);if(!p)return;const name=currentLang==='en'?(p.en||p.name):p.name,url=location.href.split('#')[0]+'#product-'+p.id,msg=`⚡ عرض سريع من Ladies First\n${name}\nالسعر: ${Number(p.price)||0} ₪${p.old&&p.old>p.price?` بدل ${Number(p.old)} ₪`:''}\nللطلب: ${url}`;window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank')}
function renderQuickOffers(){const el=document.getElementById('quickOfferGrid');if(!el)return;const list=quickOffers();el.innerHTML=list.length?list.map(p=>{const img=safeImg(mainImagesOf(p)[0],LOGO);return `<article class="quickOfferCard"><img src="${img}" onclick="openProduct(${p.id})"><div class="quickOfferBody"><b>${esc(currentLang==='en'?(p.en||p.name):p.name)}</b><div class="fprice">${Number(p.price)||0} ₪</div><div class="quickOfferActions"><button class="quickOfferBuy" onclick="event.stopPropagation();quickBuy(${p.id})">🛍️ شراء</button><button class="quickOfferWA" onclick="shareOfferWhatsApp(${p.id})"><svg class="waIcon" viewBox="0 0 448 512" aria-hidden="true"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-32.6-16.3-54-29.1-75.5-66-5.7-9.8 5.7-9.1 16.3-30.3 1.8-3.7.9-6.9-.5-9.7-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 35.2 15.2 49 16.5 66.6 13.9 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg> واتساب</button></div></div></article>`}).join(''):'<div class="empty">لا توجد عروض سريعة حاليًا.</div>'}
function featureCardHtml(p,extra=''){const img=safeImg(mainImagesOf(p)[0],LOGO);return `<article class="featureCard" onclick="openProduct(${p.id})"><img src="${img}" onerror="this.onerror=null;this.src='${LOGO}'"><div class="fcbody"><b>${esc(currentLang==='en'?(p.en||p.name):p.name)}</b><div class="fprice">${Number(p.price)||0} ₪</div>${extra}</div></article>`}
let featureTimer=null;
const featureTouchState={};
const featureDragState={};
function bindFeatureCarousel(el){
  if(!el||el.dataset.carouselBound==='1')return;
  el.dataset.carouselBound='1';
  el.style.touchAction='pan-x pan-y';
  let down=false,startX=0,startScroll=0,moved=false;
  const start=e=>{const p=e.touches?e.touches[0]:e;down=true;moved=false;startX=p.clientX;startScroll=el.scrollLeft;el.classList.add('dragging');};
  const move=e=>{if(!down)return;const p=e.touches?e.touches[0]:e,dx=p.clientX-startX;if(Math.abs(dx)>7)moved=true;if(moved){el.scrollLeft=startScroll-dx;if(e.cancelable)e.preventDefault();}};
  const end=()=>{if(!down)return;down=false;el.classList.remove('dragging');if(moved){el.dataset.suppressClick='1';setTimeout(()=>delete el.dataset.suppressClick,120);}};
  el.addEventListener('pointerdown',start,{passive:true});
  el.addEventListener('pointermove',move,{passive:false});
  el.addEventListener('pointerup',end,{passive:true});
  el.addEventListener('pointercancel',end,{passive:true});
  el.addEventListener('touchstart',start,{passive:true});
  el.addEventListener('touchmove',move,{passive:false});
  el.addEventListener('touchend',end,{passive:true});
  el.addEventListener('click',e=>{if(el.dataset.suppressClick==='1'){e.preventDefault();e.stopPropagation();delete el.dataset.suppressClick;}},true);
}
function moveFeatureCarousel(id,dir){const el=document.getElementById(id);if(!el)return;const card=el.querySelector('.featureCard');const gap=parseInt(getComputedStyle(el).gap||'10',10)||10;const amount=(card?.getBoundingClientRect().width||190)+gap;el.scrollBy({left:dir*amount,behavior:'smooth'});}
function initFeatureCarousels(){bindFeatureCarousel(document.getElementById('top5Grid'));bindFeatureCarousel(document.getElementById('bestSellersGrid'));}
function autoFeatureCarousels(){['top5Grid','bestSellersGrid'].forEach(id=>{const el=document.getElementById(id);if(!el||el.scrollWidth<=el.clientWidth+5)return;const card=el.querySelector('.featureCard');const amount=(card?.getBoundingClientRect().width||190)+10;const max=el.scrollWidth-el.clientWidth;if(el.scrollLeft>=max-4)el.scrollTo({left:0,behavior:'smooth'});else el.scrollBy({left:amount,behavior:'smooth'});});}
let featureAutoTimer=null;
function restartFeatureAuto(){clearInterval(featureAutoTimer);featureAutoTimer=setInterval(autoFeatureCarousels,3500);}

function renderFeatureSections(){
  const t=document.getElementById('top5Grid'),b=document.getElementById('bestSellersGrid');
  if(!t||!b)return;
  const top=getTop5(),best=getBestSellers();
  t.innerHTML=top.length?top.map(p=>featureCardHtml(p)).join(''):'<div class="empty">لا توجد عروض حالياً</div>';
  b.innerHTML=best.length?best.map(x=>featureCardHtml(x.p,`<div class="soldCount">مباع: ${x.qty}</div>`)).join(''):'<div class="empty">لا توجد مبيعات بعد</div>';
  t.scrollLeft=0;b.scrollLeft=0;
  initFeatureCarousels();
  restartFeatureAuto();
  renderQuickOffers();
}
function renderProducts(){const q=(document.getElementById('search').value||'').toLowerCase(),f=document.getElementById('filter').value,bf=document.getElementById('brandFilter')?.value||'';const list=products.filter(p=>(!f||p.cat===f)&&(!bf||p.brand===bf)&&(!q||(`${p.name||''} ${p.en||''} ${p.desc||''} ${p.brand||''}`).toLowerCase().includes(q)));document.getElementById('grid').innerHTML=list.map(p=>{const img=safeImg(mainImagesOf(p)[0],LOGO);const vs=variantList(p);const stock=totalStock(p);const sold=stock<=0;const defaultVariant=vs.find(v=>v.stock>0)?.name||'';const inCart=(findCartItem(p.id,defaultVariant)?.qty)||0;const soldVariants=vs.filter(v=>v.stock<=0);return `<article class="card ${sold?'soldOutCard':''}"><div class="pic" onclick="openProduct(${p.id})"><button class="favBtn ${isFavorite(p.id)?'active':''}" type="button" onclick="event.stopPropagation();toggleFavorite(${p.id})">${isFavorite(p.id)?'♥':'♡'}</button><img src="${img}" onerror="this.onerror=null;this.src='${LOGO}'">${p.onSale&&p.old>p.price?`<span class="discount">-${Math.round((1-p.price/p.old)*100)}%</span>`:''}${sold?`<div class="soldStamp">💕<span>عذرًا سيدتي،<br>خلصت الكمية🌸</span></div>`:''}</div><div class="body"><h3>${esc(currentLang==='en'?(p.en||p.name):p.name)}</h3><p>${esc(p.desc||'')}</p><div class="priceLine"><span class="price">${Number(p.price)||0} ₪</span>${p.onSale&&p.old>p.price?`<span class="old">${Number(p.old)} ₪</span>`:''}${p.onSale&&Number(p.old)>Number(p.price)?`<span class="offerText">لأجلك سيدتي</span>`:''}${Number(p.visaDiscount)>0?`<span class="visaOffer">💳 خصم Visa ${Number(p.visaDiscount)}%</span>`:''}</div>${vs.length?`<div class="variantBox"><div class="variantLabel">${currentLang==='en'?'Available colors':'الألوان المتوفرة'}</div><div class="variantChips">${vs.map(v=>`<span class="variantChip ${v.stock<=0?'sold':''}">${esc(v.name)}${v.stock<=0?' — خلص':''}</span>`).join('')}</div>${soldVariants.length<vs.length?renderVariantChooser(p):''}</div>`:''}${sold?`<div class="soldText">${currentLang==='en'?'💕 Sorry, this item is out of stock 🌸':'💕 عذرًا سيدتي، خلصت الكمية🌸'}</div><button class="waitBtn" onclick="joinWaitlist(${p.id})">${currentLang==='en'?'🔔 Join availability list':'🔔 سجّلي في قائمة التوفر'}</button><button class="similarBtn" onclick="showSimilar('${esc(p.cat).replace(/'/g,"\\'")}',${p.id})">${currentLang==='en'?'🌸 See similar items':'🌸 شوفي أشياء بتشبهها'}</button>`:`<button class="add" onclick="addSingleToCart(${p.id},selectedVariant(${p.id}))">${currentLang==='en'?'Add to cart':'أضيفي للسلة'}</button><div class="quantityBar"><button onclick="changeProductQty(${p.id},-1,selectedVariant(${p.id}))">−</button><span class="num" id="qtyNum_${p.id}">${inCart}</span><button onclick="changeProductQty(${p.id},1,selectedVariant(${p.id}))">+</button></div><small class="stockHint" id="stockHint_${p.id}">${vs.length?`متوفر من اللون ${defaultVariant}: ${variantStock(p,defaultVariant)}`:`${currentLang==='en'?`Available: ${stock}`:`متوفر: ${stock}`}`}</small>${((vs.length?variantStock(p,defaultVariant):stock)>0&&(vs.length?variantStock(p,defaultVariant):stock)<=3)?`<div class="lowStockAlert" id="lowStock_${p.id}">💕 استغلي الفرصة! آخر ${(vs.length?variantStock(p,defaultVariant):stock)} قطع فقط 🌸</div>`:''}`}</div></article>`}).join('')||'<div class="empty">لا توجد منتجات</div>';updateCount()}
function showSimilar(cat,id){document.getElementById('filter').value=cat;document.getElementById('search').value='';document.getElementById('products').scrollIntoView({behavior:'smooth'});const all=products.filter(p=>p.cat===cat&&p.id!==id);document.getElementById('grid').innerHTML=all.length?'':`<div class="empty">لا توجد أصناف مشابهة حاليًا.</div>`;if(all.length)renderProducts()}
function completeLookProducts(p){
  if(!p)return [];
  const available=products.filter(x=>x&&x.id!==p.id&&totalStock(x)>0);
  const different=available.filter(x=>x.cat!==p.cat);
  const sameBrand=different.filter(x=>p.brand&&x.brand===p.brand);
  const pool=[...sameBrand,...different.filter(x=>!sameBrand.includes(x))];
  return pool.slice(0,3);
}
function completeLookHtml(p){
  const picks=completeLookProducts(p);
  if(!picks.length)return '';
  return `<div class="completeLookBox"><h3>✨ ${currentLang==='en'?'Complete the look':'كمّلي الإطلالة'}</h3><div class="completeLookGrid">${picks.map(x=>`<button type="button" class="completeLookItem" onclick="addSingleToCart(${JSON.stringify(x.id)},'');this.classList.add('added');this.querySelector('span').textContent='${currentLang==='en'?'Added ✓':'تمت الإضافة ✓'}'"><img src="${safeImg(mainImagesOf(x)[0],LOGO)}" onerror="this.onerror=null;this.src='${LOGO}'"><b>${esc(currentLang==='en'?(x.en||x.name):x.name)}</b><small>${Number(x.price)||0} ₪</small><span>${currentLang==='en'?'Add':'أضيفي للسلة'}</span></button>`).join('')}</div></div>`;
}
function openProduct(id){const productHash='#product-'+id;if(location.hash!==productHash){history.pushState({productId:Number(id)},'',productHash);}const p=products.find(x=>x.id===id);if(!p)return;const mains=mainImagesOf(p),subs=subImagesOf(p),imgs=[...mains,...subs];document.getElementById('modalBody').innerHTML=`<div class="modalGrid"><div><img id="mainProductImg" class="mainImg" src="${safeImg(imgs[0],LOGO)}" onerror="this.onerror=null;this.src='${LOGO}'"><div class="thumbs">${imgs.map((x,i)=>`<img class="${i===0?'active':''}" src="${x}" onerror="this.style.display='none'" onclick="pickImg(this,'${esc(x).replace(/'/g,"\'")}')">`).join('')}</div></div><div><h1>${esc(currentLang==='en'?(p.en||p.name):p.name)}</h1><p>${esc(p.desc||'')}</p><div class="priceLine"><h2 class="price">${Number(p.price)||0} ₪</h2>${p.onSale&&p.old>p.price?`<span class="old">${Number(p.old)} ₪</span>`:''}${p.onSale&&Number(p.old)>Number(p.price)?`<span class="offerText">لأجلك سيدتي</span>`:''}${Number(p.visaDiscount)>0?`<span class="visaOffer">💳 خصم Visa ${Number(p.visaDiscount)}%</span>`:''}</div>${variantList(p).length?renderVariantChooser(p):''}${renderPackagingOptions()}${completeLookHtml(p)}<button class="add" onclick="addSingleToCart(${p.id},selectedVariant(${p.id}),selectedPackaging());closeModal()">${currentLang==='en'?'Add to cart':'أضيفي للسلة'}</button></div></div>`;document.getElementById('modal').style.display='flex'}
function pickImg(el,src){document.getElementById('mainProductImg').src=src;document.querySelectorAll('.thumbs img').forEach(x=>x.classList.remove('active'));el.classList.add('active')}function closeModal(){if(location.hash.indexOf('#product-')===0){history.replaceState(null,'',location.pathname+location.search);} document.getElementById('modal').style.display='none'}
const DEFAULT_PACKAGING_OPTIONS=[{id:'clear-ribbon',nameAr:'تغليف شفاف مع شبرة',nameEn:'Clear wrapping with ribbon',price:5,active:true},{id:'paper-ribbon',nameAr:'تغليف ورقي مع شبرة',nameEn:'Paper wrapping with ribbon',price:15,active:true}];
function getPackagingOptions(){let a=load('lf_packaging_options',null);if(!Array.isArray(a)||!a.length){a=DEFAULT_PACKAGING_OPTIONS.map(x=>({...x}));save('lf_packaging_options',a)}return a.filter(x=>x&&x.active!==false)}
function getPackaging(id){return getPackagingOptions().find(x=>x.id===id)||null}
function renderPackagingOptions(){const opts=getPackagingOptions();if(!opts.length)return '';return `<div class="packagingBox"><div class="packagingTitle">🎁 ${currentLang==='en'?'Would you like gift wrapping?':'هل ترغبين بطلب تغليف للمنتج؟'}</div><div class="packagingHint">${currentLang==='en'?'Choose wrapping before adding the product to your cart.':'اختاري نوع التغليف قبل إضافة المنتج إلى السلة.'}</div><label class="packagingOption"><input type="radio" name="packagingChoice" value="" checked><span class="pkgText">${currentLang==='en'?'No wrapping':'بدون تغليف'}</span><span class="pkgPrice">0 ₪</span></label>${opts.map(x=>`<label class="packagingOption"><input type="radio" name="packagingChoice" value="${esc(x.id)}"><span class="pkgText">${esc(currentLang==='en'?(x.nameEn||x.nameAr):(x.nameAr||x.nameEn))}</span><span class="pkgPrice">${Number(x.price)||0} ₪</span></label>`).join('')}</div>`}
function selectedPackaging(){return document.querySelector('input[name="packagingChoice"]:checked')?.value||''}
function findCartItem(id,variant,packagingId=''){return cart.find(i=>i.id===id&&(i.variant||'')===(variant||'')&&(i.packagingId||'')===(packagingId||''))}
function variantStock(p,variant){const vs=variantList(p);if(!vs.length)return Math.max(0,Number(p.stock)||0);const v=vs.find(x=>x.name===variant);return v?Math.max(0,v.stock):0}
function addToCart(id,qty=1,variant='',packagingId=''){const p=products.find(x=>x.id===id);if(!p)return;const vs=variantList(p);if(vs.length&&!variant){variant=vs.find(v=>v.stock>0)?.name||''}const stock=variantStock(p,variant);if(stock<=0)return alert(currentLang==='en'?'💕 Sorry, this item is out of stock 🌸':'💕 عذرًا سيدتي، خلصت الكمية🌸');let x=findCartItem(id,variant,packagingId);const current=x?Number(x.qty)||0:0;const next=current+Math.max(1,qty);if(next>stock)return alert(`💕 عذرًا سيدتي، المتوفر حاليًا ${stock} قطع فقط 🌸\nيمكنك إضافة عدد القطع المتاحة ${stock} قطع كحد أقصى.`);if(x)x.qty=next;else cart.push({id,qty:Math.max(1,qty),variant,packagingId:packagingId||''});save('lf_cart',cart);renderProducts();renderCart();lfCartHeartbeat()}

// زر "أضيفي للسلة" ينقل قطعة واحدة فقط. تكرار الضغط لا يزيد الكمية؛ الزيادة تتم حصراً من زر +.
function showCartNotice(msg){let el=document.getElementById('cartNoticeToast');if(!el){el=document.createElement('div');el.id='cartNoticeToast';el.style.cssText='position:fixed;right:50%;transform:translateX(50%);bottom:90px;z-index:9999;background:#63345e;color:#fff;padding:13px 18px;border-radius:16px;box-shadow:0 8px 24px #0003;font-weight:700;text-align:center;max-width:90%;transition:opacity .2s';document.body.appendChild(el)}el.textContent=msg;el.style.opacity='1';clearTimeout(el._timer);el._timer=setTimeout(()=>{el.style.opacity='0'},2600)}
function addSingleToCart(id,variant='',packagingId=''){const p=products.find(x=>x.id===id);if(!p)return;const vs=variantList(p);if(vs.length&&!variant){variant=vs.find(v=>v.stock>0)?.name||''}const stock=variantStock(p,variant);if(stock<=0)return alert(currentLang==='en'?'💕 Sorry, this item is out of stock 🌸':'💕 عذرًا سيدتي، خلصت الكمية🌸');const existing=findCartItem(id,variant,packagingId);if(existing){renderProducts();renderCart();return}cart.push({id,qty:1,variant,packagingId:packagingId||''});save('lf_cart',cart);clearCheckoutDraft();renderProducts();renderCart()}
function quickBuy(id,variant='',packagingId=''){const p=products.find(x=>x.id===id);if(!p)return;const vs=variantList(p);if(vs.length&&!variant)variant=vs.find(v=>v.stock>0)?.name||'';const stock=variantStock(p,variant);if(stock<=0)return alert(currentLang==='en'?'💕 Sorry, this item is out of stock 🌸':'💕 عذرًا سيدتي، خلصت الكمية🌸');const existing=findCartItem(id,variant,packagingId);if(existing){showCartNotice('سيدتي، هاد الصنف موجود أصلًا بسلتك 🩷');return}cart.push({id,qty:1,variant,packagingId:packagingId||''});save('lf_cart',cart);clearCheckoutDraft();renderProducts();openCart();setTimeout(()=>openCheckoutForm(),100)}
function changeProductQty(id,d,variant='',packagingId=''){const p=products.find(x=>x.id===id);if(!p)return;const vs=variantList(p);if(vs.length&&!variant)variant=vs.find(v=>v.stock>0)?.name||'';let x=findCartItem(id,variant,packagingId);if(!x&&d>0){addToCart(id,1,variant,packagingId);return}if(!x)return;const stock=variantStock(p,variant),next=(Number(x.qty)||0)+d;if(next>stock)return alert(`💕 عذرًا سيدتي، المتوفر حاليًا ${stock} قطع فقط 🌸\nيمكنك إضافة عدد القطع المتاحة ${stock} قطع كحد أقصى.`);x.qty=next;if(x.qty<=0)cart=cart.filter(i=>!(i.id===id&&(i.variant||'')===(variant||'')&&(i.packagingId||'')===(packagingId||'')));save('lf_cart',cart);renderProducts();renderCart();lfCartHeartbeat()}
async function openCart(){document.getElementById('drawer').style.display='block';if(lfToken())await lfLoadLoyalty();renderCart()}function closeCart(){document.getElementById('drawer').style.display='none'}
function updateCartPackaging(id,variant,packagingId,oldPackagingId=''){const x=findCartItem(id,variant||'',oldPackagingId||'');if(!x)return;x.packagingId=packagingId||'';save('lf_cart',cart);renderCart();updateCount()}
function changeCartQty(id,d,variant,packagingId){changeProductQty(id,d,variant,packagingId||'')}
function updateCount(){document.getElementById('count').textContent=cart.reduce((a,b)=>a+(Number(b.qty)||0),0)}
function getCoupons(){return load('lf_coupons',[]).filter(c=>c&&c.active!==false)}
function findCoupon(code){const c=String(code||'').trim().toUpperCase();return getCoupons().find(x=>String(x.code||'').toUpperCase()===c)||null}
let couponCode=localStorage.getItem('lf_coupon')||'';
let lfLoyalty={points:0,settings:{enabled:false,redeemEnabled:true,pointValue:0.1}};
async function lfLoadLoyalty(){if(!lfToken())return;try{const d=await lfFetch('/api/loyalty');lfLoyalty=d;const a=load(ACCOUNT_KEY,null)||{};a.points=Number(d.points||0);save(ACCOUNT_KEY,a);updateCheckoutTotal()}catch(e){console.warn('API loyalty unavailable',e.message)}}
function getPointsRedeem(){const e=document.getElementById('pointsRedeem');return Math.max(0,Math.floor(Number(e?.value)||0))}
function getCartTotals(pay,code=couponCode){let subtotal=0,visaDiscount=0,packagingTotal=0;cart.forEach(i=>{const p=products.find(x=>x.id===i.id);if(!p)return;const qty=Math.max(1,Number(i.qty)||1),line=(Number(p.price)||0)*qty;subtotal+=line;if(pay==='visa')visaDiscount+=line*(Math.max(0,Number(p.visaDiscount)||0)/100);const pkg=getPackaging(i.packagingId);if(pkg)packagingTotal+=(Number(pkg.price)||0)*qty});const afterVisa=Math.max(0,subtotal-visaDiscount);const coupon=findCoupon(code);let couponDiscount=0;if(coupon){const v=Math.max(0,Number(coupon.value)||0);couponDiscount=coupon.type==='fixed'?Math.min(afterVisa,v):afterVisa*Math.min(100,v)/100}const ship=currentShipping();const shippingFee=ship.fee;const redeemEnabled=!!lfLoyalty?.settings?.enabled&&lfLoyalty?.settings?.redeemEnabled!==false;const pv=Math.max(0,Number(lfLoyalty?.settings?.pointValue||0));const requested=getPointsRedeem();const balance=Math.max(0,Number(lfLoyalty?.points||0));const pointsRedeemed=redeemEnabled?Math.min(requested,balance):0;const loyaltyDiscount=Math.min(pointsRedeemed*pv,Math.max(0,afterVisa-couponDiscount));return {subtotal,visaDiscount,couponDiscount,packagingTotal,shippingFee,pointsRedeemed,loyaltyDiscount,total:Math.max(0,afterVisa-couponDiscount-loyaltyDiscount)+packagingTotal+shippingFee,coupon,shippingRegion:document.getElementById('shippingRegion')?.value||'westbank',shippingRegionName:currentLang==='en'?ship.en:ship.ar}}
function applyCoupon(){const input=document.getElementById('couponInput');const code=String(input?.value||'').trim().toUpperCase();if(!code)return alert(currentLang==='en'?'Enter a coupon code':'اكتبي كود الخصم');const c=findCoupon(code);if(!c)return alert(currentLang==='en'?'Invalid or expired coupon':'كود الخصم غير صحيح أو غير فعال');couponCode=code;localStorage.setItem('lf_coupon',couponCode);renderCart();alert(currentLang==='en'?'Coupon applied':'تم تطبيق كود الخصم')}
function clearCoupon(){couponCode='';localStorage.removeItem('lf_coupon');renderCart()}
function updateCheckoutTotal(){const pay=document.querySelector('input[name="pay"]:checked')?.value||'cod';const t=getCartTotals(pay);const el=document.getElementById('checkoutTotal');if(el)el.textContent=`${currentLang==='en'?'Total:':'الإجمالي:'} ${t.total.toFixed(2)} ₪`;const sh=document.getElementById('shippingLine');if(sh)sh.textContent=`${currentLang==='en'?'Delivery:':'التوصيل:'} ${t.shippingRegionName} — ${t.shippingFee.toFixed(2)} ₪`;const pkg=document.getElementById('packagingTotalLine');if(pkg)pkg.textContent=t.packagingTotal>0?`🎁 ${currentLang==='en'?'Wrapping:':'التغليف:'} +${t.packagingTotal.toFixed(2)} ₪`:'';const vd=document.getElementById('visaDiscountLine');if(vd)vd.textContent=t.visaDiscount>0?`خصم Visa: -${t.visaDiscount.toFixed(2)} ₪`:'';const cd=document.getElementById('couponDiscountLine');if(cd)cd.textContent=t.couponDiscount>0?`${currentLang==='en'?'Coupon discount:':'خصم الكوبون:'} -${t.couponDiscount.toFixed(2)} ₪`:'';const ld=document.getElementById('loyaltyDiscountLine');if(ld)ld.textContent=t.loyaltyDiscount>0?`⭐ خصم استبدال النقاط: -${t.loyaltyDiscount.toFixed(2)} ₪ (${t.pointsRedeemed} نقطة)`:''}
function getCheckoutDraft(){
  const f=document.getElementById('checkoutForm');
  if(!f)return null;
  return {
    open: f.classList.contains('open'),
    name: document.getElementById('name')?.value||'',
    phone: document.getElementById('phone')?.value||'',
    city: document.getElementById('city')?.value||'',
    address: document.getElementById('address')?.value||'',
    notes: document.getElementById('notes')?.value||'',
    shippingRegion: document.getElementById('shippingRegion')?.value||'westbank',
    countryIso: document.getElementById('checkoutCountryCode')?.value||'PS',
    pay: document.querySelector('input[name="pay"]:checked')?.value||'cod'
  };
}
function saveCheckoutDraft(){
  try{const d=getCheckoutDraft();if(d)localStorage.setItem('lf_checkout_draft',JSON.stringify(d));}catch(e){}
}
function loadCheckoutDraft(){
  try{return JSON.parse(localStorage.getItem('lf_checkout_draft')||'null')}catch(e){return null}
}
function clearCheckoutDraft(){try{localStorage.removeItem('lf_checkout_draft')}catch(e){}}
function restoreCheckoutDraft(){
  const d=loadCheckoutDraft();
  if(!d)return;
  const set=(id,v)=>{const el=document.getElementById(id);if(el&&v!=null)el.value=v};
  if(document.getElementById('checkoutCountryCode')&&d.countryIso){document.getElementById('checkoutCountryCode').value=d.countryIso;syncCountryDialPreview('checkoutCountryCode','phone')}set('name',d.name);set('phone',d.phone);set('city',d.city);set('address',d.address);set('notes',d.notes);set('shippingRegion',d.shippingRegion||'westbank');
  const pay=document.querySelector(`input[name="pay"][value="${d.pay||'cod'}"]`);if(pay)pay.checked=true;
  if(d.open){const f=document.getElementById('checkoutForm');const gate=document.querySelector('.checkoutGate');if(f){f.classList.add('open');if(gate)gate.style.display='none';}}
  updateCheckoutTotal();
}
function setupFeatureDrag(id){/* v36: native touch scrolling; no pointer hijacking. */}
function setupFeatureDrags(){/* intentionally empty; native carousel handles touch/scroll */}

function renderCart(){saveCheckoutDraft();updateCount();const el=document.getElementById('cart'),checkout=document.getElementById('checkout');if(!cart.length){clearCheckoutDraft();el.innerHTML=`<div class="empty">${currentLang==='en'?'Your cart is empty':'السلة فارغة'}</div>`;checkout.innerHTML='';return}el.innerHTML=cart.map(i=>{const p=products.find(x=>x.id===i.id);if(!p)return '';const qty=Number(i.qty)||1,totalLine=(Number(p.price)||0)*qty;return `<div class="cartrow"><div class="cartpic" onclick="openProduct(${p.id})" style="cursor:pointer"><img src="${safeImg(mainImagesOf(p)[0],LOGO)}" onerror="this.onerror=null;this.src='${LOGO}'"></div><div class="info"><b>${esc(currentLang==='en'?(p.en||p.name):p.name)}</b>${i.variant?`<div>${currentLang==='en'?'Color:':'اللون:'} ${esc(i.variant)}</div>`:''}<div class="cartPackaging"><label>🎁 ${currentLang==='en'?'Gift wrapping:':'التغليف:'}</label><select onchange="updateCartPackaging(${p.id},'${esc(i.variant||'').replace(/'/g,"\'")}',this.value,'${esc(i.packagingId||'').replace(/'/g,"\'")}')"><option value="" ${!i.packagingId?'selected':''}>${currentLang==='en'?'No wrapping':'بدون تغليف'}</option>${getPackagingOptions().map(x=>`<option value="${esc(x.id)}" ${i.packagingId===x.id?'selected':''}>${esc(currentLang==='en'?(x.nameEn||x.nameAr):(x.nameAr||x.nameEn))} +${Number(x.price)||0} ₪</option>`).join('')}</select></div><div>${Number(p.price)||0} ₪ × ${qty} = ${totalLine} ₪${getPackaging(i.packagingId)?` + ${Number(getPackaging(i.packagingId).price)||0} ₪ ${currentLang==='en'?'wrapping':'تغليف'}`:''}</div>${Number(p.visaDiscount)>0?`<div class="visaOffer">💳 ${currentLang==='en'?'Visa discount':'خصم Visa'} ${Number(p.visaDiscount)}%</div>`:''}</div><div class="qty"><button onclick="changeCartQty(${p.id},-1,'${esc(i.variant||'').replace(/'/g,"\'")}','${esc(i.packagingId||'').replace(/'/g,"\'")}')">−</button><b>${qty}</b><button onclick="changeCartQty(${p.id},1,'${esc(i.variant||'').replace(/'/g,"\'")}','${esc(i.packagingId||'').replace(/'/g,"\'")}')">+</button></div></div>`}).join('');const t=getCartTotals(document.querySelector('input[name="pay"]:checked')?.value||'cod');checkout.innerHTML=`<div class="checkoutGate"><button class="add" type="button" onclick="openCheckoutForm()">🧾 ${currentLang==='en'?'Complete order / Buyer details':'إتمام الطلب وإدخال بيانات المشتري'}</button></div><div id="checkoutForm" class="checkoutForm"><div class="orderFormTitle">🧾 ${currentLang==='en'?'Complete order & buyer details':'إتمام الطلب وإدخال بيانات المشتري'}</div><div class="checkout"><b id="checkoutTotal"></b><div id="visaDiscountLine" class="visaOffer" style="margin-top:8px"></div><div id="couponDiscountLine" class="couponLine" style="margin-top:8px"></div><div id="loyaltyDiscountLine" class="couponLine" style="margin-top:8px"></div><div class="couponBox"><b>🎟️ ${currentLang==='en'?'Discount code':'كود الخصم'}</b><div class="couponRow"><input id="couponInput" class="field" value="${esc(couponCode)}" placeholder="${currentLang==='en'?'Enter coupon code':'أدخلي كود الخصم'}"><button onclick="applyCoupon()">${currentLang==='en'?'Apply':'تطبيق'}</button>${couponCode?`<button class="danger" onclick="clearCoupon()">×</button>`:''}</div>${t.coupon?`<div class="couponApplied">✓ ${currentLang==='en'?'Applied':'تم تطبيق'}: ${esc(t.coupon.code)}</div>`:''}</div><div id="loyaltyBox" class="couponBox" style="display:${lfLoyalty?.settings?.enabled?'block':'none'}"><b>⭐ استبدال النقاط</b><div class="small">رصيدك: ${Number(lfLoyalty?.points||0)} نقطة — قيمة النقطة: ${Number(lfLoyalty?.settings?.pointValue||0).toFixed(2)} ₪</div><div class="couponRow"><input id="pointsRedeem" class="field" type="number" min="0" max="${Number(lfLoyalty?.points||0)}" step="1" value="0" oninput="updateCheckoutTotal()"><button type="button" onclick="document.getElementById('pointsRedeem').value=${Number(lfLoyalty?.points||0)};updateCheckoutTotal()">استخدام الكل</button></div></div><input class="field" id="name" placeholder="${currentLang==='en'?'Full name':'الاسم الكامل'}"><div class="phoneIntlBox checkoutPhoneBox"><div class="phoneIntlTop"><select id="checkoutCountryCode" class="field countrySelect" onchange="syncCountryDialPreview('checkoutCountryCode','phone')"></select><span class="phoneDialHint" id="phoneDialHint">+970</span></div><input class="field" id="phone" placeholder="${currentLang==='en'?'Mobile number without country code':'رقم الجوال بدون مفتاح الدولة'}" inputmode="tel" autocomplete="tel-national"></div><input class="field" id="city" placeholder="${currentLang==='en'?'City':'المدينة'}"><input class="field" id="address" placeholder="${currentLang==='en'?'Full address':'العنوان بالتفصيل'}"><div class="shippingBox"><b>🚚 ${currentLang==='en'?'Delivery area':'منطقة التوصيل'}</b><select id="shippingRegion" onchange="updateCheckoutTotal()"><option value="westbank">${currentLang==='en'?'West Bank — 20 ₪':'الضفة الغربية — 20 ₪'}</option><option value="jerusalem">${currentLang==='en'?'Jerusalem — 35 ₪':'القدس — 35 ₪'}</option><option value="inside">${currentLang==='en'?'Inside 1948 — 70 ₪':'الداخل — 70 ₪'}</option></select><div id="packagingTotalLine" class="shippingInfo"></div><div id="shippingLine" class="shippingInfo"></div></div><textarea class="field" id="notes" placeholder="${currentLang==='en'?'Notes':'ملاحظات'}"></textarea><div class="pay"><label><input type="radio" name="pay" value="cod" checked onchange="updateCheckoutTotal()"> ${currentLang==='en'?'Cash on delivery':'الدفع عند الاستلام'}</label><label><input type="radio" name="pay" value="visa" onchange="updateCheckoutTotal()"> 💳 Visa</label></div><button class="add" onclick="placeOrder()">${currentLang==='en'?'Place order':'إنهاء الطلب'}</button></div></div>`;restoreCheckoutDraft();initCountrySelectors();syncCountryDialPreview('checkoutCountryCode','phone');updateCheckoutTotal()}
function openCheckoutForm(){const f=document.getElementById('checkoutForm');if(f){f.classList.add('open');const gate=document.querySelector('.checkoutGate');if(gate)gate.style.display='none';setTimeout(()=>{const n=document.getElementById('name');if(n)n.focus();f.scrollIntoView({behavior:'smooth',block:'start'});},80);}}

